const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

// AES-CBC decryption service for encrypted session tokens
const BLOCK_SIZE = 16;
const KEY_FILE = '/var/task/keys/session.key';
const LOG_DIR = '/tmp/decrypt-logs';

function loadKey() {
  try {
    return fs.readFileSync(KEY_FILE);
  } catch (e) {
    // Fallback to environment variable
    return Buffer.from(process.env.SESSION_KEY || 'a'.repeat(32), 'hex');
  }
}

function pkcs7Validate(buffer) {
  if (buffer.length === 0 || buffer.length % BLOCK_SIZE !== 0) {
    return { valid: false, error: 'invalid_length' };
  }
  const padByte = buffer[buffer.length - 1];
  if (padByte === 0 || padByte > BLOCK_SIZE) {
    return { valid: false, error: 'invalid_padding_byte' };
  }
  for (let i = buffer.length - padByte; i < buffer.length; i++) {
    if (buffer[i] !== padByte) {
      return { valid: false, error: 'padding_mismatch' };
    }
  }
  return { valid: true, data: buffer.slice(0, buffer.length - padByte) };
}

function decryptToken(encryptedHex) {
  const key = loadKey();
  const encryptedBuf = Buffer.from(encryptedHex, 'hex');

  if (encryptedBuf.length < BLOCK_SIZE * 2) {
    return { success: false, error: 'ciphertext_too_short' };
  }

  const iv = encryptedBuf.slice(0, BLOCK_SIZE);
  const ciphertext = encryptedBuf.slice(BLOCK_SIZE);

  const decipher = crypto.createDecipheriv('aes-256-cbc', key, iv);
  decipher.setAutoPadding(false);

  let decrypted;
  try {
    decrypted = Buffer.concat([decipher.update(ciphertext), decipher.final()]);
  } catch (e) {
    return { success: false, error: 'decryption_failed' };
  }

  const paddingResult = pkcs7Validate(decrypted);
  if (!paddingResult.valid) {
    // Log failed attempts for security monitoring
    logDecryptionAttempt(encryptedHex, paddingResult.error);
    return { success: false, error: paddingResult.error };
  }

  return { success: true, token: paddingResult.data.toString('utf8') };
}

function logDecryptionAttempt(input, error) {
  try {
    if (!fs.existsSync(LOG_DIR)) {
      fs.mkdirSync(LOG_DIR, { recursive: true });
    }
    const logEntry = JSON.stringify({
      timestamp: Date.now(),
      input_prefix: input.substring(0, 64),
      error: error
    }) + '\n';
    fs.appendFileSync(path.join(LOG_DIR, 'attempts.log'), logEntry);
  } catch (e) {
    // Silently fail logging
  }
}

exports.handler = async (event) => {
  const body = JSON.parse(event.body || '{}');
  const { token } = body;

  if (!token) {
    return {
      statusCode: 400,
      body: JSON.stringify({ error: 'missing_token' })
    };
  }

  const startTime = Date.now();
  const result = decryptToken(token);
  const elapsed = Date.now() - startTime;

  if (!result.success) {
    return {
      statusCode: 403,
      headers: { 'X-Decrypt-Time': String(elapsed) },
      body: JSON.stringify({ error: result.error })
    };
  }

  return {
    statusCode: 200,
    headers: { 'X-Decrypt-Time': String(elapsed) },
    body: JSON.stringify({ session: result.token, valid: true })
  };
};
